package com.digitalbase.ticketing.controller;import com.digitalbase.ticketing.dto.ClientProductRequest;import com.digitalbase.ticketing.dto.ClientProductResponse;import com.digitalbase.ticketing.service.ClientProductService;import lombok.RequiredArgsConstructor;import org.springframework.http.HttpStatus;import org.springframework.http.ResponseEntity;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.List;@RestController@RequestMapping("/api")@RequiredArgsConstructorpublic class ClientProductController {    private final ClientProductService clientProductService;    @PreAuthorize("hasRole('ADMIN')")    @PostMapping("/admin/client-products")    public ResponseEntity<ClientProductResponse> assignProduct(@RequestBody ClientProductRequest request) {        return new ResponseEntity<>(clientProductService.assignProductToClient(request), HttpStatus.CREATED);    }    @PreAuthorize("hasAnyRole('CLIENT', 'ADMIN')")    @GetMapping("/client/my-products")    public ResponseEntity<List<ClientProductResponse>> getMyProducts(Authentication authentication) {        String email = authentication.getName();        return ResponseEntity.ok(clientProductService.getMyProducts(email));    }}